        "title": "La nansa que demanava una altra idea",
        "summary": "La reparació d’una bossa canvia quan la propietària explica com la fa servir i on la guarda.",
        "paragraphs": [
          "L’Elena va arribar al taller de la plaça amb la seva bossa verda. Cada dimarts la feia servir per portar les partitures i una ampolla d’aigua a l’assaig del cor. La Irene, la reparadora, va deixar una capsa de fils sobre la taula. Al costat hi havia l’Hugo i l’Asha, dos infants del barri que dibuixaven objectes del taller.",
          "Un dels extrems de la nansa es descosia. La Irene el va subjectar i va examinar la tela. L’Elena va afegir una altra queixa: quan la bossa era plena, la nansa estreta li molestava al palmell. Volia arreglar la costura, però també arribar a l’assaig sense haver de canviar contínuament la bossa de mà.",
          "—I si hi posem una nansa llarga? —va preguntar l’Hugo. L’Elena va dibuixar un armari a l’aire amb el dit. A casa la guardava penjada d’un ganxo, damunt d’un prestatge. Amb més llargada, la bossa tocaria aquell prestatge i quedaria torta. La Irene va cosir l’extrem descosit mentre l’Asha pensava en una funda per cobrir el centre de la nansa.",
          "La Irene va preparar dues mostres de funda encoixinada amb retalls. La primera, gruixuda i rodona, gairebé no deixava que l’Elena tanqués els dits. La segona era més plana i li era còmoda. L’Elena va triar aquella, de tela de color teula. Va demanar un tancament que permetés treure-la per rentar-la; la Irene li va ensenyar com quedaria abans de cosir-lo.",
          "Abans d’acabar la funda, la Irene va proposar una volta pel porxo. L’Elena va posar-hi les partitures i l’ampolla, va aixecar la bossa i va caminar. Continuava a la mateixa altura i la nansa ja no li molestava. Després d’aquella prova, la Irene va acabar la funda. L’Hugo va esborrar la nansa llarga del dibuix i hi va afegir el tancament. L’Elena va recollir les seves coses: encara arribava al cor."
        ],
